CREATE TABLE sfi_result AS SELECT cdid FROM cd AS me WHERE 2 > (SELECT COUNT(*) FROM cd AS rownum__emulation WHERE (me.genreid IS NOT NULL AND rownum__emulation.genreid IS NULL) OR (me.genreid IS NOT NULL AND rownum__emulation.genreid IS NOT NULL AND rownum__emulation.genreid < me.genreid) OR ((me.genreid = rownum__emulation.genreid OR (me.genreid IS NULL AND rownum__emulation.genreid IS NULL)) AND rownum__emulation.cdid > me.cdid));